if (points.size() <= 3) {
    return points;
}

// Find pivot (point with lowest y, leftmost if tie)
int pivotIndex = 0;
for (int i = 1; i < points.size(); i++) {
    if (points[i].y() < points[pivotIndex].y() ||
        (points[i].y() == points[pivotIndex].y() && points[i].x() < points[pivotIndex].x())) {
        pivotIndex = i;
    }
}
Point_2 pivot = points[pivotIndex];

// Sort points by polar angle
std::vector<Point_2> sortedPoints;
for (int i = 0; i < points.size(); i++) {
    if (i != pivotIndex) {
        sortedPoints.push_back(points[i]);
    }
}

std::sort(sortedPoints.begin(), sortedPoints.end(), [&pivot](const Point_2& a, const Point_2& b) {
    int orientation = orientation_test(pivot, a, b);
    if (orientation == 0) {
        // Collinear - keep the farther one
        double distA = (a.x() - pivot.x()) * (a.x() - pivot.x()) + (a.y() - pivot.y()) * (a.y() - pivot.y());
        double distB = (b.x() - pivot.x()) * (b.x() - pivot.x()) + (b.y() - pivot.y()) * (b.y() - pivot.y());
        return distA < distB;
    }
    return orientation > 0; // CCW
});

// Remove collinear points at same angle (keep farthest)
std::vector<Point_2> filteredPoints;
filteredPoints.push_back(pivot);
for (int i = 0; i < sortedPoints.size(); i++) {
    while (i + 1 < sortedPoints.size()) {
        int orient = orientation_test(pivot, sortedPoints[i], sortedPoints[i + 1]);
        if (orient == 0) {
            i++;
        } else {
            break;
        }
    }
    filteredPoints.push_back(sortedPoints[i]);
}

// Graham scan
std::vector<Point_2> hull;
hull.push_back(filteredPoints[0]);
hull.push_back(filteredPoints[1]);

for (int i = 2; i < filteredPoints.size(); i++) {
    while (hull.size() > 1) {
        int orient = orientation_test(hull[hull.size() - 2], hull[hull.size() - 1], filteredPoints[i]);
        if (orient > 0) { // Left turn
            break;
        }
        hull.pop_back();
    }
    hull.push_back(filteredPoints[i]);
}

return hull;

